client_script:
var rumba_unit_by_name = {};
var EMAIL_RUMBA_INDUK = "rumba.united@gmail.com";

var WILAYAH_METHOD = "rumba16.api.get_rumba_wilayah_aktif";
var UNIT_METHOD = "rumba16.api.get_rumba_units_by_kota";

var rumba_wilayah = [];
var mode_fallback = false;

function toggle_field(fieldname, show) {
	// defensif: sebagian field toggle bisa tidak terpasang di web form
	if (!frappe.web_form.fields_dict[fieldname]) return;

	frappe.web_form.set_df_property(fieldname, "hidden", show ? 0 : 1);

	if (!show) {
		frappe.web_form.set_value(fieldname, "");
	}
}

function toggle_fields() {
	toggle_field("nama_sekolah", frappe.web_form.get_value("anak_sudah_sekolah") === "Ya");
	toggle_field("kelas", frappe.web_form.get_value("anak_sudah_sekolah") === "Ya");
	toggle_field("jelaskan_kebutuhan_khusus_anak", frappe.web_form.get_value("anak_berkebutuhan_khusus") === "Ya");
	toggle_field("nama_saudara", frappe.web_form.get_value("saudara_di_rumba") === "Ya");
	toggle_field("belajar_di_unit_rumba", frappe.web_form.get_value("saudara_di_rumba") === "Ya");
	toggle_field("durasi_les", frappe.web_form.get_value("les_serupa") === "Ya");
	toggle_field("level_yang_dicapai", frappe.web_form.get_value("les_serupa") === "Ya");
	toggle_field("untuk_jawaban_lainnya", Boolean(frappe.web_form.get_value("lainnya")));
	toggle_field("ukuran_kaos", Boolean(frappe.web_form.get_value("kaos")));
}

function set_hidden_value(fieldname, value) {
	if (frappe.web_form.fields_dict[fieldname]) {
		frappe.web_form.set_value(fieldname, value || "");
	}
}

function set_email_rumba_induk() {
	set_hidden_value("email_rumba_induk", EMAIL_RUMBA_INDUK);
}

function set_tanggal_pendaftaran() {
	if (frappe.web_form.fields_dict.tanggal_pendaftaran) {
		frappe.web_form.set_value(
			"tanggal_pendaftaran",
			frappe.datetime.get_today()
		);
	}
}

function refresh_select_field(fieldname, options) {
	var f = frappe.web_form.fields_dict[fieldname];

	if (!f) {
		console.warn("Field tidak ditemukan:", fieldname);
		return;
	}

	f.df.options = options.join("\n");

	if (f.$input) {
		f.$input.empty();
		options.forEach(function (option) {
			f.$input.append(
				$("<option></option>").attr("value", option).text(option)
			);
		});
	}

	f.refresh();
}

function set_autocomplete_options(fieldname, options) {
	var f = frappe.web_form.fields_dict[fieldname];
	if (f && typeof f.set_data === "function") {
		f.set_data(options);
	}
}

function ubah_tombol_sukses_webform() {
	var interval = setInterval(function () {
		var buttons = document.querySelectorAll("a, button");

		buttons.forEach(function (button) {
			var text = (button.innerText || button.textContent || "").trim();

			if (text === "Submit another response") {
				button.innerText = "Kembali ke beranda";

				button.onclick = function (event) {
					event.preventDefault();
					window.location.href = "https://bimbelrumba.id";
				};

				if (button.tagName.toLowerCase() === "a") {
					button.setAttribute("href", "https://bimbelrumba.id");
				}

				clearInterval(interval);
			}
		});
	}, 300);
}

function jaga_opsi_autocomplete(fieldname, ambil_opsi) {
	var f = frappe.web_form.fields_dict[fieldname];
	if (!f) return;

	if (f.$input && !f.__rumba_jaga) {
		f.__rumba_jaga = true;
		f.$input.on("focus", function () {
			set_autocomplete_options(fieldname, ambil_opsi());
		});
	}

	[700, 1600, 3200].forEach(function (ms) {
		setTimeout(function () {
			set_autocomplete_options(fieldname, ambil_opsi());
		}, ms);
	});
}

function opsi_provinsi_saat_ini() {
	return rumba_wilayah.map(function (p) {
		return { value: p.kode_provinsi, label: p.nama_provinsi };
	});
}

function opsi_kota_saat_ini() {
	var provinsi = get_provinsi(frappe.web_form.get_value("kode_provinsi"));
	return provinsi
		? provinsi.kota.map(function (k) {
			return { value: k.kode_kota, label: k.nama_kota };
		})
		: [];
}

function get_provinsi(kode_provinsi) {
	for (var i = 0; i < rumba_wilayah.length; i++) {
		if (rumba_wilayah[i].kode_provinsi === kode_provinsi) return rumba_wilayah[i];
	}
	return null;
}

function get_kota(kode_provinsi, kode_kota) {
	var provinsi = get_provinsi(kode_provinsi);
	if (!provinsi) return null;
	for (var i = 0; i < provinsi.kota.length; i++) {
		if (provinsi.kota[i].kode_kota === kode_kota) return provinsi.kota[i];
	}
	return null;
}

function kosongkan_unit() {
	rumba_unit_by_name = {};
	set_hidden_value("nama_unit", "");
	set_hidden_value("kode_unit", "");
	set_hidden_value("email_unit", "");
	refresh_select_field("nama_unit", [""]);
}

function set_unit_options(units, pertahankan_nilai) {
	rumba_unit_by_name = {};

	var options = [""];

	units.forEach(function (unit) {
		var unit_value = unit.name || unit.nama_unit;

		if (unit_value) {
			options.push(unit_value);
			rumba_unit_by_name[unit_value] = unit;
		}
	});

	var nilai_unit = pertahankan_nilai
		? frappe.web_form.get_value("nama_unit")
		: "";

	if (!pertahankan_nilai) {
		set_hidden_value("nama_unit", "");
		set_hidden_value("kode_unit", "");
		set_hidden_value("email_unit", "");
	}

	refresh_select_field("nama_unit", options);

	if (units.length === 1 && !nilai_unit) {
		frappe.web_form.set_value(
			"nama_unit",
			units[0].name || units[0].nama_unit
		);
	}
}

function isi_opsi_provinsi() {
	set_autocomplete_options("kode_provinsi", rumba_wilayah.map(function (p) {
		return { value: p.kode_provinsi, label: p.nama_provinsi };
	}));
}

function isi_opsi_kota(kode_provinsi, pertahankan_nilai) {
	var provinsi = get_provinsi(kode_provinsi);
	var opsi = provinsi
		? provinsi.kota.map(function (k) {
			return { value: k.kode_kota, label: k.nama_kota };
		})
		: [];

	set_autocomplete_options("nama_kota", opsi);

	var nilai_kota = pertahankan_nilai
		? frappe.web_form.get_value("nama_kota")
		: "";

	if (!pertahankan_nilai) {
		frappe.web_form.set_value("nama_kota", "");
		kosongkan_unit();
	}

	if (opsi.length === 1 && !nilai_kota) {
		frappe.web_form.set_value("nama_kota", opsi[0].value);
	}
}

function isi_opsi_unit(kode_provinsi, kode_kota, pertahankan_nilai) {
	var kota = get_kota(kode_provinsi, kode_kota);
	set_unit_options(kota ? kota.unit : [], pertahankan_nilai);
}

function aktifkan_fallback() {
	mode_fallback = true;
	frappe.web_form.set_df_property("kode_provinsi", "reqd", 0);
	frappe.web_form.set_df_property("kode_provinsi", "hidden", 1);
	load_unit_options_fallback(frappe.web_form.get_value("nama_kota"));
}

function load_unit_options_fallback(kode_kota) {
	if (!kode_kota) {
		kosongkan_unit();
		return;
	}

	kosongkan_unit();

	frappe.call({
		method: UNIT_METHOD,
		args: { kode_kota: kode_kota },
		callback: function (response) {
			set_unit_options(response.message || [], false);
		},
		error: function (error) {
			console.error("Gagal mengambil unit:", error);
			kosongkan_unit();
		}
	});
}

function muat_wilayah() {
	frappe.call({
		method: WILAYAH_METHOD,
		callback: function (r) {
			rumba_wilayah = r.message || [];
			isi_opsi_provinsi();
			jaga_opsi_autocomplete("kode_provinsi", opsi_provinsi_saat_ini);
			jaga_opsi_autocomplete("nama_kota", opsi_kota_saat_ini);

			var provinsi = frappe.web_form.get_value("kode_provinsi");
			var kota = frappe.web_form.get_value("nama_kota");

			if (provinsi) isi_opsi_kota(provinsi, true);
			if (provinsi && kota) isi_opsi_unit(provinsi, kota, true);

			if (rumba_wilayah.length === 1 && !provinsi) {
				frappe.web_form.set_value(
					"kode_provinsi", rumba_wilayah[0].kode_provinsi
				);
			}
		},
		error: function () {
			aktifkan_fallback();
		}
	});
}

frappe.web_form.after_load = function () {
	toggle_fields();
	set_email_rumba_induk();
	set_tanggal_pendaftaran();
	muat_wilayah();
	ubah_tombol_sukses_webform();
};

frappe.web_form.after_save = function () {
	ubah_tombol_sukses_webform();
};

frappe.web_form.on("kode_provinsi", function (field, value) {
	if (mode_fallback) return;
	isi_opsi_kota(value, false);
});

frappe.web_form.on("nama_kota", function (field, value) {
	if (mode_fallback) {
		load_unit_options_fallback(value);
		return;
	}
	isi_opsi_unit(frappe.web_form.get_value("kode_provinsi"), value, false);
});

frappe.web_form.on("nama_unit", function (field, value) {
	var unit = rumba_unit_by_name[value];

	set_hidden_value(
		"kode_unit",
		unit && unit.kode_unit ? unit.kode_unit : ""
	);

	set_hidden_value(
		"email_unit",
		unit && unit.email_unit ? unit.email_unit : ""
	);

	set_email_rumba_induk();
});

// defensif: hanya pasang handler untuk field yang benar-benar ada di web form
["anak_sudah_sekolah", "anak_berkebutuhan_khusus", "saudara_di_rumba", "les_serupa", "lainnya", "kaos"].forEach(function (fieldname) {
	if (frappe.web_form.fields_dict[fieldname]) {
		frappe.web_form.on(fieldname, function () { toggle_fields(); });
	}
});
